import type { Editor } from "@tiptap/vue-3";
import { computed, shallowRef, toValue, watch } from "vue";
import type { ComputedRef, MaybeRefOrGetter } from "vue";

/**
 * Bumps on every editor transaction so selectors can re-evaluate.
 * Vue has no `useEditorState`, so reactivity is driven by the editor events.
 */
export const useEditorVersion = (
  editor: MaybeRefOrGetter<Editor | null | undefined>
) => {
  const version = shallowRef(0);
  const bump = () => {
    version.value += 1;
  };

  watch(
    () => toValue(editor),
    (current, _previous, onCleanup) => {
      if (!current || current.isDestroyed) {
        return;
      }
      current.on("transaction", bump);
      current.on("selectionUpdate", bump);
      bump();
      onCleanup(() => {
        current.off("transaction", bump);
        current.off("selectionUpdate", bump);
      });
    },
    { immediate: true }
  );

  return version;
};

export const useEditorState = <T>(
  editor: MaybeRefOrGetter<Editor | null | undefined>,
  selector: (editor: Editor | null) => T
): ComputedRef<T> => {
  const version = useEditorVersion(editor);
  return computed(() => {
    // touched so the computed re-runs on every editor transaction
    version.value;
    const current = toValue(editor);
    return selector(current && !current.isDestroyed ? current : null);
  });
};

export const shallowEqual = <T extends Record<string, unknown>>(
  a: T,
  b: T
): boolean => {
  if (a === b) {
    return true;
  }
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) {
    return false;
  }
  return ak.every((k) => a[k] === b[k]);
};

import type { Editor } from "@tiptap/vue-3";
import { inject } from "vue";
import type { ComputedRef, InjectionKey } from "vue";

import type { RichTextEditorIcons } from "./icon-types";
import type { RichTextEditorLabels } from "./labels";
import type { RichTextEditorVariant } from "./types";

export interface RichTextEditorContext {
  editor: ComputedRef<Editor | null>;
  labels: ComputedRef<RichTextEditorLabels>;
  icons: ComputedRef<RichTextEditorIcons>;
  variant: ComputedRef<RichTextEditorVariant>;
  editable: ComputedRef<boolean>;
}

export const richTextEditorKey: InjectionKey<RichTextEditorContext> =
  Symbol("RichTextEditor");

export const useRichTextEditorContext = (): RichTextEditorContext => {
  const context = inject(richTextEditorKey, null);
  if (!context) {
    throw new Error(
      "useRichTextEditorContext must be used within RichTextEditor"
    );
  }
  return context;
};

import type { ChainedCommands } from "@tiptap/core";
import type { Editor } from "@tiptap/vue-3";
import { computed, defineComponent, h } from "vue";

import { useEditorState } from "./composables";
import { useRichTextEditorContext } from "./context";
import type { RichTextEditorIcons } from "./icon-types";
import type { RichTextEditorLabels } from "./labels";
import RichTextEditorControl from "./ui/rte-control.vue";

type IsActiveConfig =
  | { name: string; attributes?: Record<string, unknown> | string }
  | { attrs: Record<string, unknown> };

type ChainCommand = (
  attributes?: Record<string, unknown> | string
) => Pick<ChainedCommands, "run">;

interface CreateControlProps {
  label: keyof RichTextEditorLabels;
  iconKey: Exclude<keyof RichTextEditorIcons, "languageIcons">;
  isActive?: IsActiveConfig;
  isDisabled?: (editor: Editor) => boolean;
  operation: { name: string; attributes?: Record<string, unknown> | string };
}

const resolveIsActive = (
  editor: Editor | null,
  config?: IsActiveConfig
): boolean => {
  if (!editor || !config) {
    return false;
  }
  if ("attrs" in config) {
    return editor.isActive(config.attrs);
  }
  return editor.isActive(config.name, config.attributes);
};

export const createControl = ({
  label,
  iconKey,
  isActive,
  isDisabled,
  operation,
}: CreateControlProps) => {
  return defineComponent({
    name: `RteControl${String(iconKey)}`,
    inheritAttrs: false,
    props: {
      class: { type: String, default: "" },
    },
    setup(props) {
      const { editor, labels, icons } = useRichTextEditorContext();

      const active = useEditorState(editor, (current) =>
        resolveIsActive(current, isActive)
      );
      const disabled = useEditorState(editor, (current) =>
        current ? (isDisabled?.(current) ?? false) : true
      );
      const ariaLabel = computed(() => labels.value[label]);

      const run = () => {
        const current = editor.value;
        if (!current || current.isDestroyed) {
          return;
        }
        const commands = current.chain().focus() as unknown as Record<
          string,
          ChainCommand
        >;
        commands[operation.name]?.(operation.attributes).run();
      };

      return () =>
        h(
          RichTextEditorControl,
          {
            active: active.value,
            class: props.class,
            disabled: disabled.value,
            "aria-label": ariaLabel.value,
            title: ariaLabel.value,
            onClick: run,
          },
          () => h(icons.value[iconKey], { class: "rte-editor-icon" })
        );
    },
  });
};

