/* ── Main Editor Wrapper ── */
.rte-root {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background-color: var(--background);
  transition:
    border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}

.rte-editor-icon {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

button.rte-control-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 2rem;
  min-width: 2rem;
  padding: 0;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    transform 100ms ease-out;
}

button.rte-control-button:active {
  transform: scale(0.96);
}

/* ── Editor Content ── */
.rte-content .ProseMirror {
  outline: 0;
  padding: var(--spacing, 0.75rem);
  min-height: 140px;
}

.rte-content .ProseMirror > *:last-child {
  margin-bottom: 0;
}

.rte-content .ProseMirror p.is-editor-empty:first-of-type::before {
  content: attr(data-placeholder);
  pointer-events: none;
  user-select: none;
  float: left;
  height: 0;
  color: var(--muted-foreground);
  transition: opacity 150ms ease-out;
}

.rte-content .ProseMirror p {
  margin-top: 0;
  margin-bottom: 0.75rem;
  line-height: 1.75;
}

.rte-content .ProseMirror h1,
.rte-content .ProseMirror h2,
.rte-content .ProseMirror h3,
.rte-content .ProseMirror h4,
.rte-content .ProseMirror h5,
.rte-content .ProseMirror h6,
.rte-content .ProseMirror p {
  margin-top: 0;
}

.rte-content .ProseMirror h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  margin-bottom: 1rem;
  margin-top: 1.5rem;
}
.rte-content .ProseMirror h1:first-child {
  margin-top: 0;
}

.rte-content .ProseMirror h2 {
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: -0.025em;
  margin-bottom: 0.75rem;
  margin-top: 1.25rem;
}
.rte-content .ProseMirror h2:first-child {
  margin-top: 0;
}

.rte-content .ProseMirror h3 {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  margin-top: 1rem;
}
.rte-content .ProseMirror h3:first-child {
  margin-top: 0;
}

.rte-content .ProseMirror h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  margin-top: 0.75rem;
}
.rte-content .ProseMirror h4:first-child {
  margin-top: 0;
}

.rte-content .ProseMirror h5 {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  margin-top: 0.75rem;
}
.rte-content .ProseMirror h5:first-child {
  margin-top: 0;
}

.rte-content .ProseMirror h6 {
  font-size: 0.875rem;
  font-weight: 500;
  margin-bottom: 0.5rem;
  margin-top: 0.75rem;
}
.rte-content .ProseMirror h6:first-child {
  margin-top: 0;
}

.rte-content .ProseMirror ul {
  list-style-type: disc;
  padding-left: 1.5rem;
  margin-bottom: 0.75rem;
}

.rte-content .ProseMirror ol {
  list-style-type: decimal;
  padding-left: 1.5rem;
  margin-bottom: 0.75rem;
}

.rte-content .ProseMirror li {
  line-height: 1.75;
}

.rte-content .ProseMirror li > p {
  margin-bottom: 0;
}

.rte-content .ProseMirror ul li,
.rte-content .ProseMirror ol li {
  margin-top: 2px;
}

.rte-content .ProseMirror blockquote {
  border-left: 3px solid var(--border);
  padding-left: 1rem;
  margin-top: 1rem;
  margin-bottom: 1rem;
  color: var(--muted-foreground);
  font-style: italic;
}

.rte-content .ProseMirror pre code {
  color: inherit;
  background: none;
  padding: 0;
  font-weight: 400;
}

.rte-content .ProseMirror pre {
  background: #1e1e2e;
  color: #cdd6f4;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  padding: 1rem;
  margin-top: 1rem;
  margin-bottom: 1rem;
  overflow-x: auto;
  font-family: var(--font-mono);
  font-size: 0.875rem;
}

.rte-content .ProseMirror pre code {
  background: none;
  color: inherit;
  border: none;
  font-size: 0.875rem;
  padding: 0;
}

.rte-content .ProseMirror hr {
  border: none;
  border-top: 1px solid var(--border);
  margin-top: 1.5rem;
  margin-bottom: 1.5rem;
}

.rte-content .ProseMirror a {
  color: var(--primary);
  text-decoration: underline;
  text-underline-offset: 4px;
  cursor: pointer;
  transition:
    color 150ms ease-out,
    text-decoration-color 150ms ease-out;
  text-decoration-color: color-mix(in srgb, var(--primary) 40%, transparent);
}

.rte-content .ProseMirror a:hover {
  color: color-mix(in srgb, var(--primary) 80%, transparent);
  text-decoration-color: color-mix(in srgb, var(--primary) 80%, transparent);
}

/* Syntax Highlighting */
.rte-content .ProseMirror pre .hljs-comment,
.rte-content .ProseMirror pre .hljs-quote {
  color: #6c7086;
}

.rte-content .ProseMirror pre .hljs-variable,
.rte-content .ProseMirror pre .hljs-template-variable,
.rte-content .ProseMirror pre .hljs-attribute,
.rte-content .ProseMirror pre .hljs-tag,
.rte-content .ProseMirror pre .hljs-regexp,
.rte-content .ProseMirror pre .hljs-link,
.rte-content .ProseMirror pre .hljs-name,
.rte-content .ProseMirror pre .hljs-selector-id,
.rte-content .ProseMirror pre .hljs-selector-class {
  color: #89b4fa;
}

.rte-content .ProseMirror pre .hljs-number,
.rte-content .ProseMirror pre .hljs-meta,
.rte-content .ProseMirror pre .hljs-built_in,
.rte-content .ProseMirror pre .hljs-builtin-name,
.rte-content .ProseMirror pre .hljs-literal,
.rte-content .ProseMirror pre .hljs-type,
.rte-content .ProseMirror pre .hljs-params {
  color: #fab387;
}

.rte-content .ProseMirror pre .hljs-string,
.rte-content .ProseMirror pre .hljs-symbol,
.rte-content .ProseMirror pre .hljs-bullet {
  color: #a6e3a1;
}

.rte-content .ProseMirror pre .hljs-title,
.rte-content .ProseMirror pre .hljs-section {
  color: #f9e2af;
}

.rte-content .ProseMirror pre .hljs-keyword,
.rte-content .ProseMirror pre .hljs-selector-tag {
  color: #cba6f7;
}

/* Object/JSON keys & HTML/XML attribute names (previously missing) */
.rte-content .ProseMirror pre .hljs-attr {
  color: #89b4fa;
}

/* JSDoc-style tags, e.g. @param, @returns */
.rte-content .ProseMirror pre .hljs-doctag {
  color: #f38ba8;
  font-weight: 600;
}

/* Operators & punctuation (finer-grained grammars) */
.rte-content .ProseMirror pre .hljs-operator,
.rte-content .ProseMirror pre .hljs-punctuation {
  color: #9399b2;
}

/* CSS selector attributes/pseudo-classes, e.g. [type="text"], :hover */
.rte-content .ProseMirror pre .hljs-selector-attr,
.rte-content .ProseMirror pre .hljs-selector-pseudo {
  color: #94e2d5;
}

/* Language-level variables, e.g. this, super */
.rte-content .ProseMirror pre .hljs-variable.language_ {
  color: #cba6f7;
  font-style: italic;
}

/* Template literal substitutions, e.g. ${...} */
.rte-content .ProseMirror pre .hljs-subst {
  color: #cdd6f4;
}

.rte-content .ProseMirror pre .hljs-emphasis {
  font-style: italic;
}
.rte-content .ProseMirror pre .hljs-strong {
  font-weight: 700;
}

.rte-content .ProseMirror pre .hljs-addition {
  color: #a6e3a1;
  background-color: color-mix(in srgb, #a6e3a1 10%, transparent);
}

.rte-content .ProseMirror pre .hljs-deletion {
  color: #f38ba8;
  background-color: color-mix(in srgb, #f38ba8 10%, transparent);
}

.rte-content .ProseMirror code {
  font-size: 0.875em;
  font-weight: 500;
  background: color-mix(in srgb, var(--muted) 70%, transparent);
  padding: 0.125rem 0.375rem;
  border-radius: calc(var(--radius) - 4px);
  transition: background-color 150ms ease-out;
