      0px 4px 12px 0px oklch(0 0 0 / 0.3);
  }
}

.rte-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  background-color: var(--background);
  z-index: 1;
  border-end-end-radius: var(--radius);
