  backdrop-filter: blur(8px);
  box-shadow:
    0px 0px 0px 1px oklch(0 0 0 / 0.04),
    0px -4px 12px 0px oklch(0 0 0 / 0.05);
}

@media (prefers-color-scheme: dark) {
  .rte-footer[data-sticky] {
    box-shadow:
      0px 0px 0px 1px oklch(1 0 0 / 0.06),
      0px -4px 12px 0px oklch(0 0 0 / 0.3);
