  );
}

.rte-toolbar--subtle + .rte-content + .rte-footer {
  background-color: var(--muted);
}
.rte-toolbar--compact + .rte-content + .rte-footer {
  background-color: var(--muted);
}

@media (max-width: 640px) {
  .rte-toolbar {
    flex-wrap: nowrap;
    overflow-x: auto;
    justify-content: flex-start;
    scrollbar-width: none;
    -ms-overflow-style: none;
    -webkit-overflow-scrolling: touch;
    --rte-toolbar-fade-end: 1.5rem;
    mask-image: linear-gradient(
      to right,
      transparent,
      black var(--rte-toolbar-fade-start),
      black calc(100% - var(--rte-toolbar-fade-end)),
      transparent
    );
  }
