    .rte-toolbar {
      --rte-toolbar-fade-end: 0px;
      animation: rte-toolbar-fade linear both;
      animation-timeline: scroll(self inline);
    }
  }
}

@property --rte-toolbar-fade-start {
  syntax: "<length>";
