}

.rte-task-list p {
  margin: 0;
  padding: 0;
}

.rte-task-list label {
  display: inline-flex;
  align-items: center;
  height: 1.75em;
  cursor: pointer;
}

.rte-task-list input[type="checkbox"] {
  cursor: pointer;
  appearance: none;
