}
.rte-embed-wrapper[data-align="center"] {
  justify-content: center;
  text-align: center;
}
.rte-embed-wrapper[data-align="right"] {
  justify-content: flex-end;
  text-align: right;
}

.rte-embed-wrapper[data-selected] .rte-embed {
