.rte-resize-handle--left {
  top: 0;
  bottom: 0;
  left: -3px;
  width: 6px;
  cursor: ew-resize;
  background: transparent;
}

.rte-resize-handle--left::after {
  content: "";
  position: absolute;
  inset: 4px 1px;
  width: 2px;
  background: var(--primary);
  border-radius: 1px;
  transition:
    width 150ms ease-out,
    inset 150ms ease-out;
}

.rte-resize-handle--left:hover::after {
  width: 4px;
  inset: 4px 0;
}

.rte-resize-handle--right {
  top: 0;
  bottom: 0;
  right: -3px;
  width: 6px;
  cursor: ew-resize;
  background: transparent;
}

.rte-resize-handle--right::after {
  content: "";
  position: absolute;
  inset: 4px 1px;
  width: 2px;
  background: var(--primary);
  border-radius: 1px;
  transition:
