  right: 0;
  bottom: -3px;
  height: 6px;
  cursor: ns-resize;
  background: transparent;
}

.rte-resize-handle--bottom::after {
  content: "";
  position: absolute;
  left: 4px;
  right: 4px;
  height: 2px;
  background: var(--primary);
  border-radius: 1px;
  bottom: 1px;
  transition:
    height 150ms ease-out,
    bottom 150ms ease-out;
}

.rte-resize-handle--bottom:hover::after {
  height: 4px;
  bottom: 0;
}

.rte-resize-handle--corner {
  width: 12px;
  height: 12px;
  background: var(--primary);
  border: 2px solid var(--background);
  border-radius: 2px;
  transition: transform 150ms ease-out;
