.rte-bubble-btn:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

.rte-bubble-btn:active {
  transform: scale(0.96);
}

.rte-bubble-btn--active {
  color: var(--primary);
  background: var(--accent);
}

.rte-bubble-btn-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1rem;
  height: 1rem;
}

.rte-bubble-btn-icon svg {
  width: 100%;
  height: 100%;
}

.rte-bubble-btn-text {
  max-width: 5rem;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rte-bubble-overlay {
  position: fixed;
  inset: 0;
  z-index: 999;
}

.rte-bubble-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 1000;
  min-width: 150px;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  padding: 0.25rem;
  margin-top: 4px;
  transform-origin: top left;
  animation: rte-bubble-pop-in 0.25s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.rte-bubble-dropdown--language {
  min-width: 160px;
  max-height: 320px;
  overflow-y: auto;
  scrollbar-width: thin;
}

.rte-bubble-dropdown-item {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0.5rem;
  position: relative;
  z-index: 1;
  width: 100%;
  padding: 0.375rem 0.5rem;
  font-size: 0.8125rem;
  color: var(--muted-foreground);
  background: transparent;
  border: none;
  border-radius: calc(var(--radius) - 4px);
  cursor: pointer;
  text-align: left;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out;
}

.rte-bubble-dropdown-item:hover,
.rte-bubble-dropdown-item:focus-visible {
  color: var(--foreground);
}

.rte-bubble-dropdown-pill {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: calc(var(--radius) - 4px);
  background: color-mix(in srgb, var(--primary) 6%, transparent);
  opacity: 0;
  transition:
    top 220ms cubic-bezier(0.22, 1, 0.36, 1),
    left 220ms cubic-bezier(0.22, 1, 0.36, 1),
    width 220ms cubic-bezier(0.22, 1, 0.36, 1),
    height 220ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 150ms ease-out;
}

.rte-bubble-dropdown-pill--visible {
  opacity: 1;
}

.rte-bubble-dropdown-item--active {
  color: var(--primary);
  background-color: color-mix(in srgb, var(--primary) 10%, transparent);
}

.rte-bubble-dropdown-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--muted-foreground);
  width: 1rem;
  height: 1rem;
}

.rte-bubble-dropdown-icon svg {
  width: 100%;
  height: 100%;
}

.rte-bubble-dropdown-item--active .rte-bubble-dropdown-icon {
  color: var(--primary);
}

.rte-bubble-dropdown-divider {
  height: 1px;
  background: var(--border);
  margin: 0.25rem 0;
}

.rte-bubble-dropdown--color {
  min-width: auto;
  padding: 0.5rem;
}

.rte-bubble-dropdown--color .rte-bubble-dropdown-divider {
  margin: 0.5rem 0 0.375rem;
}

.rte-bubble-color-section {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.rte-bubble-color-label {
  padding: 0 0.125rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
  font-weight: 700;
  line-height: 1;
}

.rte-bubble-color-grid {
  display: grid;
  grid-template-columns: repeat(5, 1.5rem);
  justify-content: center;
  gap: 0.375rem;
}

.rte-bubble-color-recent {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.375rem;
}

.rte-bubble-color-swatch {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  padding: 0;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition:
    transform 120ms cubic-bezier(0.34, 1.56, 0.64, 1),
    background-color 100ms ease-out,
    border-color 100ms ease-out,
    color 100ms ease-out,
    box-shadow 120ms ease-out;
}

.rte-bubble-color-swatch:hover {
  transform: scale(1.1);
}

.rte-bubble-color-swatch:active {
  transform: scale(0.96);
}

.rte-bubble-color-swatch:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 1px;
}

.rte-bubble-color-swatch--text {
  background: transparent;
  border-color: var(--swatch-color);
  color: var(--swatch-color);
}

.rte-bubble-color-swatch--text.rte-bubble-color-swatch--active {
  background: var(--swatch-color);
  border-color: var(--swatch-color);
  color: var(--swatch-check);
}

.rte-bubble-color-swatch--highlight {
  background: var(--swatch-color);
  border-color: transparent;
  color: var(--swatch-check);
}

.rte-bubble-color-swatch--highlight.rte-bubble-color-swatch--active {
  box-shadow: 0 0 0 2px
    color-mix(in srgb, var(--swatch-color) 55%, var(--popover-foreground));
}

.rte-bubble-color-glyph {
  font-size: 0.625rem;
  font-weight: 700;
  line-height: 1;
}

.rte-bubble-color-check {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 0.75rem;
  height: 0.75rem;
  color: var(--swatch-check);
}

.rte-bubble-color-check svg {
  width: 100%;
  height: 100%;
}

/* ── Suppress transitions on theme switch ── */
.rte-theme-transitioning *,
.rte-theme-transitioning *::before,
.rte-theme-transitioning *::after {
  transition: none !important;
}

